-- Destination coordinates and pin positions on images/dest-globe.png (727 x 479)
-- (generated by database/tools/import_destination_map.py). Safe to re-run.
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS `destination_map` (
  `slug` VARCHAR(160) NOT NULL PRIMARY KEY,
  `latitude` DECIMAL(8,5) NOT NULL,
  `longitude` DECIMAL(8,5) NOT NULL,
  `map_x` DECIMAL(6,2) DEFAULT NULL,
  `map_y` DECIMAL(6,2) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE latitude=VALUES(latitude), longitude=VALUES(longitude), map_x=VALUES(map_x), map_y=VALUES(map_y);
